using Microsoft.Azure.WebJobs;
using Microsoft.Extensions.Logging;

public static class ProcessTelemetryFunction
{
    [FunctionName("ProcessTelemetryFunction")]
    public static void Run(
        [EventHubTrigger("telemetry", ConsumerGroup = "$Default", Connection = "EventHubConnection")] EventData[] events,
        ILogger log)
    {
        foreach (var evt in events)
        {
            var body = Encoding.UTF8.GetString(evt.Body.Array, evt.Body.Offset, evt.Body.Count);
            log.LogInformation($"Received: {body}");
        }
    }
}
